# Calculate NPTEL Final Score
def calculate_nptel_score(assignment_avg, proctored_score):
    # assignment_avg out of 100, proctored_score out of 100
    total = (assignment_avg * 0.25) + (proctored_score * 0.75)
    return round(total, 2)

print("Final Score:", calculate_nptel_score(80, 65))
